import{_ as i,o as a,c as n,ag as l}from"./chunks/framework.PVHj0As1.js";const h="/pub-blog/assets/image-20250105154516700.Cqq104fL.png",p="/pub-blog/assets/image-20250105154650672.CcsymVbW.png",t="/pub-blog/assets/image-20250105155715639.BmGRgGmW.png",k="/pub-blog/assets/image-20250105154810895.DH8GQzgU.png",e="/pub-blog/assets/image-20250105160500387.B8vj-80Z.png",b=JSON.parse('{"title":"鸿蒙元服务实战-笑笑五子棋（5）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（5）/鸿蒙元服务实战-笑笑五子棋（5）.md","filePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（5）/鸿蒙元服务实战-笑笑五子棋（5）.md","lastUpdated":1736065340000,"__rawMarkdown":"# 鸿蒙元服务实战-笑笑五子棋（5）\\n\\n来到最后一章了，这一章节讲两个部分。一是**笑笑五子棋**的卡片制作，二就是发布上架。\\n\\n\\n\\n## 卡片介绍\\n\\nForm Kit（卡片开发框架）提供了一种在桌面、锁屏等系统入口嵌入显示应用信息的开发框架和API，可以将应用内用户关注的重要\\n\\n信息或常用操作抽取到服务卡片（以下简称“卡片”）上，通过将卡片添加到桌面上，以达到信息展示、服务直达的便捷体验效果。\\n\\n![image-20250105154516700](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%885%EF%BC%89.assets/image-20250105154516700.png)\\n\\n## 新建卡片\\n\\n卡片类型分为两种：\\n\\n1. 静态卡片 功能稍弱\\n2. 动态卡片 功能强一些\\n\\n![image-20250105154650672](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%885%EF%BC%89.assets/image-20250105154650672.png)\\n\\n3. 选择卡片的属性\\n\\n   ![image-20250105155715639](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%885%EF%BC%89.assets/image-20250105155715639.png)\\n\\n4. 然后你就得到了以下文件\\n\\n   ![image-20250105154810895](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%885%EF%BC%89.assets/image-20250105154810895.png)\\n\\n\\n\\n\\n\\n## 卡片文件解释\\n\\n### EntryFormAbility.ets\\n\\n> entry/src/main/ets/entryformability/EntryFormAbility.ets\\n\\n该文件可以定义卡片的生命周期，传递数据给卡片等\\n\\n### WidgetCard\\n\\n> entry/src/main/ets/widget/pages/WidgetCard.ets\\n\\n该文件是卡片的主要展示和业务功能页面。 卡片外观、功能主要由它来提供\\n\\n\\n\\n### form_config.json\\n\\n> entry/src/main/resources/base/profile/form_config.json\\n\\n该文件是卡片的配置文件，比如卡片的图标、卡片的名字、卡片的种类等等都可以在这配置\\n\\n\\n\\n\\n\\n## 获取卡片宽度\\n\\n卡片的api和元服务的api稍有区别，所以在开发的需要额外注意\\n\\n这里在 `entry/src/main/ets/entryformability/EntryFormAbility.ets` 内，可以设置卡片创建的时获取卡片的宽度\\n\\n因为卡片有不同的规格尺寸，所以可以动态来获取。\\n\\n```jsx\\n  onAddForm(want: Want) {\\n    let formData: Record<string, number> = {\\n      \\"canwidth\\": px2vp((want.parameters?.[formInfo.FormParam.WIDTH_KEY] as number) * 2),\\n    };\\n    return formBindingData.createFormBindingData(formData);\\n  }\\n```\\n\\n 卡片中是无法使用 `AppStorage`，所以需要使用Localstorage来代替，进行数据传递\\n\\n卡片中接收\\n\\n```jsx\\n@Entry\\n@Component\\nstruct WidgetCard {\\n  @LocalStorageProp(\\"canwidth\\")\\n  canwidth: number = 0\\n  @LocalStorageProp(\\"canwidth\\")\\n  canheight: number = 0\\n```\\n\\n## 完成卡片下棋逻辑\\n\\n因为卡片的下棋逻辑和宿主-元服务本身几乎一致。因此在实际开发中，可以将它们共同的逻辑抽离出来方便管理。这里就cv复用了。\\n\\n```jsx\\n@Entry\\n@Component\\nstruct WidgetCard {\\n  @LocalStorageProp(\\"canwidth\\")\\n  canwidth: number = 0\\n  @LocalStorageProp(\\"canwidth\\")\\n  canheight: number = 0\\n  settings: RenderingContextSettings = new RenderingContextSettings(true);\\n  ctx: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);\\n  // 棋盘参数\\n  gridSize: number = 15;\\n  cellSize: number = this.canwidth / this.gridSize;\\n  radius: number = this.cellSize / 2 - 5; // 棋子的半径\\n  // 棋盘数据\\n  board: number[][] = []\\n  currentPlayer: number = 1; // 当前玩家 (1: 黑子, 2: 白子)\\n  gameOver: boolean = false;\\n  @State\\n  textContent: string = \\"\\"\\n  // 处理玩家落子\\n  handleClick = async (event: ClickEvent) => {\\n    if (this.gameOver) {\\n      return;\\n    }\\n\\n    const x = event.x;\\n    const y = event.y;\\n\\n    const col = Math.floor(x / this.cellSize);\\n    const row = Math.floor(y / this.cellSize);\\n\\n    if (this.board[row] && this.board[row][col] === 0) {\\n      this.board[row][col] = this.currentPlayer;\\n      this.drawBoard();\\n\\n      if (this.checkWin(row, col)) {\\n        this.textContent = this.currentPlayer === 1 ? \'黑子胜利!\' : \'白子胜利!\';\\n        this.gameOver = true;\\n        // AlertDialog.show({ message: this.textContent })\\n\\n\\n      } else {\\n        this.currentPlayer = this.currentPlayer === 1 ? 2 : 1;\\n        this.textContent = this.currentPlayer === 1 ? \'轮到黑子落子\' : \'轮到白子落子\';\\n      }\\n    } else {\\n      // promptAction.showToast({ message: `请点击中棋盘对位位置` })\\n    }\\n  }\\n\\n  aboutToAppear(): void {\\n\\n  }\\n\\n  // 绘制棋盘\\n  drawBoard = () => {\\n    this.ctx.clearRect(0, 0, this.canwidth, this.canwidth);\\n\\n    // 绘制网格\\n    this.ctx.strokeStyle = \\"#000\\";\\n    this.ctx.lineWidth = 1;\\n    for (let i = 0; i < this.gridSize; i++) {\\n      this.ctx.beginPath();\\n      this.ctx.moveTo(this.cellSize * i, 0);\\n      this.ctx.lineTo(this.cellSize * i, this.canwidth);\\n      this.ctx.stroke();\\n\\n      this.ctx.beginPath();\\n      this.ctx.moveTo(0, this.cellSize * i);\\n      this.ctx.lineTo(this.canwidth, this.cellSize * i);\\n      this.ctx.stroke();\\n    }\\n\\n    // 绘制已落的棋子\\n    for (let row = 0; row < this.gridSize; row++) {\\n      for (let col = 0; col < this.gridSize; col++) {\\n        if (this.board[row][col] !== 0) {\\n          this.ctx.beginPath();\\n          this.ctx.arc(col * this.cellSize + this.cellSize / 2, row * this.cellSize + this.cellSize / 2, this.radius, 0,\\n            2 * Math.PI);\\n          this.ctx.fillStyle = this.board[row][col] === 1 ? \'black\' : \'white\';\\n          this.ctx.fill();\\n          this.ctx.stroke();\\n        }\\n      }\\n    }\\n  }\\n  // 判断是否有五子连珠\\n  checkWin = (row: number, col: number) => {\\n    interface abc {\\n      dr: number\\n      dc: number\\n    }\\n\\n    const directions: abc[] = [\\n      { dr: 0, dc: 1 }, // 水平\\n      { dr: 1, dc: 0 }, // 垂直\\n      { dr: 1, dc: 1 }, // 主对角线\\n      { dr: 1, dc: -1 }// 副对角线\\n    ];\\n\\n    for (let i = 0; i < directions.length; i++) {\\n      const dr = directions[i].dr\\n      const dc = directions[i].dc\\n      let count = 1;\\n\\n      // 向一个方向检查\\n      for (let i = 1; i < 5; i++) {\\n        let r = row + dr * i;\\n        let c = col + dc * i;\\n        if (r >= 0 && r < this.gridSize && c >= 0 && c < this.gridSize && this.board[r][c] === this.currentPlayer) {\\n          count++;\\n        } else {\\n          break;\\n        }\\n      }\\n\\n      // 向另一个方向检查\\n      for (let i = 1; i < 5; i++) {\\n        let r = row - dr * i;\\n        let c = col - dc * i;\\n        if (r >= 0 && r < this.gridSize && c >= 0 && c < this.gridSize && this.board[r][c] === this.currentPlayer) {\\n          count++;\\n        } else {\\n          break;\\n        }\\n      }\\n\\n      // 如果连续五个相同的棋子，则胜利\\n      if (count >= 5) {\\n        return true;\\n      }\\n    }\\n\\n    return false;\\n  }\\n  // 初始化游戏\\n  initGame = () => {\\n    this.board = []\\n    for (let index = 0; index < this.gridSize; index++) {\\n      const arr: number[] = []\\n      for (let index2 = 0; index2 < this.gridSize; index2++) {\\n        arr.push(0)\\n\\n      }\\n      this.board.push(arr)\\n\\n    }\\n    this.currentPlayer = 1;\\n    this.gameOver = false;\\n    this.textContent = \'轮到黑子落子\';\\n    this.drawBoard();\\n  }\\n\\n  build() {\\n    Stack({ alignContent: Alignment.TopStart }) {\\n      Canvas(this.ctx)\\n        .width(this.canwidth)\\n        .height(this.canwidth)\\n        .backgroundColor(Color.Orange)\\n        .onReady(() => {\\n          this.cellSize = this.canwidth / this.gridSize;\\n          this.radius = this.cellSize / 2 - 5; // 棋子的半径\\n          this.initGame()\\n        })\\n        .onClick(\\n          this.handleClick\\n        )\\n\\n      Text(this.textContent)\\n        .fontSize(14)\\n        .padding(5)\\n        .fontColor(Color.White)\\n        .fontWeight(700)\\n\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n\\n```\\n\\n\\n\\n\\n\\n## 调整卡片的图标和名字\\n\\n主要业务开发完毕了，可以调整卡片的展示信息\\n\\n![image-20250105160500387](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%885%EF%BC%89.assets/image-20250105160500387.png)\\n\\n这部分信息在  `entry/src/main/resources/base/profile/form_config.json`中配置:\\n\\n1. `displayName ` 标题\\n2. `description` 简介\\n\\n```jsx\\n{\\n  \\"forms\\": [\\n    {\\n      \\"name\\": \\"widget\\",\\n      \\"displayName\\": \\"$string:widget_display_name\\",\\n      \\"description\\": \\"$string:widget_desc\\",\\n      \\"src\\": \\"./ets/widget/pages/WidgetCard.ets\\",\\n      \\"uiSyntax\\": \\"arkts\\",\\n      \\"window\\": {\\n        \\"designWidth\\": 720,\\n        \\"autoDesignWidth\\": true\\n      },\\n      \\"colorMode\\": \\"auto\\",\\n      \\"isDynamic\\": true,\\n      \\"isDefault\\": true,\\n      \\"updateEnabled\\": false,\\n      \\"scheduledUpdateTime\\": \\"10:30\\",\\n      \\"updateDuration\\": 1,\\n      \\"defaultDimension\\": \\"4*4\\",\\n      \\"supportDimensions\\": [\\n        \\"2*2\\",\\n        \\"4*4\\"\\n      ]\\n    }\\n  ]\\n}\\n```\\n\\n\\n\\n## 发布上架\\n\\n最后，如果要将卡片发布上架，还需要做一些小处理\\n\\n1. 设置你的元服务的展示图标\\n2. 配置证书\\n3. 打包成Hap\\n4. 在AGC平台上发布上架等等\\n5. 具体流程可以参考底部的文章\\n\\n\\n\\n\\n\\n## 参考链接\\n\\n1. [卡片开发](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/formkit-overview-V5)\\n2. [HarmonyOS Next 实战卡片开发 01](https://juejin.cn/post/7432314654287872010)\\n3. [HarmonyOS Next 实战卡片开发 02](https://juejin.cn/post/7433035654400245811)\\n4. [HarmonyOS Next 实战卡片开发 03](https://juejin.cn/post/7433422988358189107)\\n5. [HarmonyOS Next 最新 元服务新建到上架全流程](https://juejin.cn/post/7441761663701041161)\\n\\n\\n\\n\\n\\n\\n\\n## 代码仓库\\n\\n```\\nhttps://gitee.com/ukSir/laughing-at-gomoku\\n```\\n\\n\\n\\n## 总结\\n\\n至此，**笑笑五子棋**的开发上架流程已经完毕。\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。"}'),r={name:"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（5）/鸿蒙元服务实战-笑笑五子棋（5）.md"};function E(d,s,g,y,c,F){return a(),n("div",null,[...s[0]||(s[0]=[l("",48)])])}const C=i(r,[["render",E]]);export{b as __pageData,C as default};
